import networkx as nx

n = 17
k = 4

G = nx.Graph()
G.add_nodes_from(range(n))

for i in range(n):
    for j in range(1, k // 2 + 1):
        G.add_edge(i, (i + j) % n)

if k % 2 == 1:
    if n % 2 == 0:
        for i in range(n // 2):
            G.add_edge(i, i + n // 2)
    else:
        G.add_edge(0, n // 2)
        G.add_edge(0, n // 2 + 1)
        for i in range(1, n // 2):
            G.add_edge(i, i + n // 2 + 1)

print("Connectivity:", nx.node_connectivity(G))
edges = sorted([tuple(sorted(e)) for e in G.edges()])
print("Edges:", edges)
